package com.cloudticket.inventory.api; import com.cloudticket.inventory.security.InventoryAuthorization; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/inventory") public class InternalInventoryController { private final InventoryAuthorization policy=new InventoryAuthorization(); @PostMapping("/locks/{id}/release") public ResponseEntity<?> release(@PathVariable String id,@RequestHeader(value="X-User-Permissions",defaultValue="")String p,@RequestBody Map<String,String> body){if(!policy.canRelease(p,body.get("reason")))return ResponseEntity.status(HttpStatus.FORBIDDEN).build();return ResponseEntity.ok(Map.of("id",id,"status","RELEASED"));} @PostMapping("/seats/{id}/adjust") public ResponseEntity<?> adjust(@PathVariable String id,@RequestHeader(value="X-User-Permissions",defaultValue="")String p,@RequestBody Map<String,String> body){if(!policy.canAdjust(p,body.get("reason")))return ResponseEntity.status(HttpStatus.FORBIDDEN).build();return ResponseEntity.ok(Map.of("id",id,"status",body.getOrDefault("status","AVAILABLE")));}}
